from datetime import date
def m1_features(item,as_of):
 t=as_of[11:16];h,m=map(int,t.split(':'));left=max(0,1320-h*60-m)
 pace30=item['sold_last_30min']/30;pace60=item['sold_last_60min']/60
 pace=max(pace30,pace60);inventory=item['inventory_at_decision'];day=date.fromisoformat(as_of[:10])
 return dict(sku_code=item['sku_code'],time=t,prepared_qty=item['prepared_qty'],inventory_at_decision=inventory,sold_last_30min=item['sold_last_30min'],sold_last_60min=item['sold_last_60min'],shelf_inventory=item['shelf_inventory'],backroom_inventory=item['backroom_inventory'],previous_discount_pct=item['current_discount_pct'],baseline_announced_2100_pct=item['baseline_announced_2100_pct'],minutes_to_close=left,sales_pace_units_per_minute=pace,pace_acceleration=pace30-pace60,inventory_cover_minutes=inventory/pace if pace>0 else None,projected_surplus_at_current_pace=max(0,inventory-pace*left),weekday_iso=day.isoweekday(),is_weekend=int(day.weekday()>=5),list_price_vnd=item['list_price_vnd'],current_unit_price_vnd=item['current_unit_price_vnd'],unit_production_cost_vnd_assumed=item.get('unit_production_cost_vnd_assumed'),unit_disposal_cost_vnd_assumed=item.get('unit_disposal_cost_vnd_assumed'),markdown_action_cost_vnd_assumed=item.get('markdown_action_cost_vnd_assumed',0),qualitative_hot_sku_user_report=item.get('qualitative_hot_sku_user_report',0),observed_buyers_last30=item.get('observed_buyers_last30',0),observed_stockout_last60_minutes=item.get('observed_stockout_last60_minutes',0),prior_day_rain_mm=item['morning_features'].get('prior_day_rain_mm'),event_stratum=item['morning_features'].get('event_stratum'))
